  if(!data){f.nextRaid=time+1800;return f;}
  f.fort=n(data.fort,0,5);f.wall=n(data.wall,180,180+f.fort*80);
  f.guards=[0,1,2].map(i=>n(data.guards?.[i],f.guards[i],20));
  f.prisoners=n(data.prisoners,0,20);f.loot=n(data.loot,30,200);
  prepareMilitary(f);
  if(Array.isArray(data.vehicles))f.vehicles=data.vehicles.filter(v=>MILITARY[v.kind]).slice(0,8).map((v,i)=>({id:'vehicle'+i,kind:v.kind,...frontierVehicleHome(Math.min(data.vehicles.length,8),i),hp:v.kind==='tank'?220:120,driver:null,cooldown:0,recover:0,ry:0}));
  f.nextRaid=data.scheduleVersion===3&&data.phase!=='attack'?time+n(data.nextRaid-time,1800,2400):time+1800;
